# 유틸리티 함수들

def get_related_tables(table_name: str) -> List[str]:
    """특정 테이블과 관련된 모든 테이블 목록 반환"""
    if table_name not in TABLE_RELATION_MAP:
        logger.warning(f"테이블 '{table_name}'에 대한 관계 정보가 없습니다.")
        return []
    
    related_tables = set()
    for relation in TABLE_RELATION_MAP[table_name]:
        if relation['type'] == 'outgoing':
            related_tables.add(relation['target_table'])
        else:  # incoming
            related_tables.add(relation['source_table'])
    
    return list(related_tables)

def get_deletion_impact(table_name: str, column_name: str) -> List[Dict]:
    """데이터 삭제 시 영향을 받는 테이블들 반환"""
    impacts = []
    
    if table_name not in TABLE_RELATION_MAP:
        return impacts
    
    for relation in TABLE_RELATION_MAP[table_name]:
        if (relation['type'] == 'outgoing' and 
            relation['source_column'] == column_name):
            impacts.append({
                'affected_table': relation['target_table'],
                'affected_column': relation['target_column'],
                'relationship_type': relation['relationship_type'],
                'impact_level': 'high' if relation['match_count'] > 100 else 'medium' if relation['match_count'] > 10 else 'low'
            })
    
    return impacts

def get_required_additions(table_name: str, column_name: str) -> List[Dict]:
    """데이터 추가 시 필요한 연관 테이블들 반환"""
    requirements = []
    
    if table_name not in TABLE_RELATION_MAP:
        return requirements
    
    for relation in TABLE_RELATION_MAP[table_name]:
        if (relation['type'] == 'incoming' and 
            relation['target_column'] == column_name):
            
            # 관계 타입에 따라 필수 여부 결정
            is_required = relation['relationship_type'] in ['perfect_match', 'table2_subset_of_table1']
            
            requirements.append({
                'required_table': relation['source_table'],
                'required_column': relation['source_column'],
                'relationship_type': relation['relationship_type'],
                'is_required': is_required,
                'priority': 'high' if is_required else 'medium'
            })
    
    return requirements

def find_relationship_path(source_table: str, target_table: str, max_depth: int = 3) -> List[List[str]]:
    """두 테이블 간의 관계 경로 찾기"""
    if source_table == target_table:
        return [[source_table]]
    
    if source_table not in TABLE_RELATION_MAP:
        return []
    
    visited = set()
    paths = []
    
    def dfs(current_table: str, current_path: List[str], depth: int):
        if depth > max_depth:
            return
        
        if current_table == target_table:
            paths.append(current_path[:])
            return
        
        if current_table in visited:
            return
        
        visited.add(current_table)
        
        if current_table in TABLE_RELATION_MAP:
            for relation in TABLE_RELATION_MAP[current_table]:
                next_table = (relation['target_table'] if relation['type'] == 'outgoing' 
                            else relation['source_table'])
                
                if next_table not in current_path:  # 순환 방지
                    current_path.append(next_table)
                    dfs(next_table, current_path, depth + 1)
                    current_path.pop()
        
        visited.remove(current_table)
    
    dfs(source_table, [source_table], 0)
    return paths

def get_table_relationship_info(table1: str, table2: str) -> Optional[Dict]:
    """두 테이블 간의 직접적인 관계 정보 반환"""
    for rel_key, rel_info in TABLE_RELATIONSHIPS.items():
        if ((rel_info['source_table'] == table1 and rel_info['target_table'] == table2) or
            (rel_info['source_table'] == table2 and rel_info['target_table'] == table1)):
            return rel_info
    
    return None

def get_high_impact_relationships(min_match_count: int = 100) -> List[Dict]:
    """높은 영향도를 가진 관계들 반환"""
    high_impact = []
    
    for rel_key, rel_info in TABLE_RELATIONSHIPS.items():
        if rel_info['match_count'] >= min_match_count:
            high_impact.append(rel_info)
    
    return sorted(high_impact, key=lambda x: x['match_count'], reverse=True)

def get_integrity_issues() -> List[Dict]:
    """데이터 정합성 문제가 있는 관계들 반환"""
    issues = []
    
    for rel_key, rel_info in TABLE_RELATIONSHIPS.items():
        if rel_info['source_only_count'] > 0 or rel_info['target_only_count'] > 0:
            issues.append({
                'relationship': rel_key,
                'source_table': rel_info['source_table'],
                'target_table': rel_info['target_table'],
                'source_orphans': rel_info['source_only_count'],
                'target_orphans': rel_info['target_only_count'],
                'severity': 'high' if max(rel_info['source_only_count'], rel_info['target_only_count']) > 100 else 'medium'
            })
    
    return sorted(issues, key=lambda x: max(x['source_orphans'], x['target_orphans']), reverse=True)

def search_relationships(keyword: str) -> List[Dict]:
    """키워드로 관계 검색"""
    results = []
    keyword_lower = keyword.lower()
    
    for rel_key, rel_info in TABLE_RELATIONSHIPS.items():
        if (keyword_lower in rel_info['source_table'].lower() or
            keyword_lower in rel_info['target_table'].lower() or
            keyword_lower in rel_info['source_column'].lower() or
            keyword_lower in rel_info['target_column'].lower()):
            results.append(rel_info)
    
    return results

# 통계 정보
def get_relationship_statistics() -> Dict:
    """관계 분석 통계 정보 반환"""
    total_relationships = len(TABLE_RELATIONSHIPS)
    
    relationship_types = {}
    total_matches = 0
    total_integrity_issues = 0
    
    for rel_info in TABLE_RELATIONSHIPS.values():
        rel_type = rel_info['relationship_type']
        relationship_types[rel_type] = relationship_types.get(rel_type, 0) + 1
        total_matches += rel_info['match_count']
        
        if rel_info['source_only_count'] > 0 or rel_info['target_only_count'] > 0:
            total_integrity_issues += 1
    
    return {
        'total_relationships': total_relationships,
        'total_data_matches': total_matches,
        'relationship_types': relationship_types,
        'integrity_issues_count': total_integrity_issues,
        'unique_tables': len(set([rel['source_table'] for rel in TABLE_RELATIONSHIPS.values()] + 
                                [rel['target_table'] for rel in TABLE_RELATIONSHIPS.values()]))
    }
